function makeUrlHandler(value) {
  if (!value) return "";
  let clean = value.trim().toLowerCase();
  clean = clean.replace(/[^a-z0-9]+/g, "-");
  clean = clean.replace(/^-+|-+$/g, "");
  return clean;
}

let urlHandler = makeUrlHandler(rawName);

return urlHandler;
